/**
 * 图像基础工具：全部纯函数，零依赖。
 * 图像统一表示为 { width, height, data: Uint8ClampedArray(RGBA) }。
 */

export function toGray(img) {
  const { width, height, data } = img;
  const gray = new Float32Array(width * height);
  for (let i = 0; i < width * height; i++) {
    const o = i * 4;
    gray[i] = 0.299 * data[o] + 0.587 * data[o + 1] + 0.114 * data[o + 2];
  }
  return gray;
}

/** 水平方向梯度幅值（Sobel 的 x 分量取绝对值）。 */
export function gradX(gray, width, height) {
  const out = new Float32Array(width * height);
  for (let y = 1; y < height - 1; y++) {
    for (let x = 1; x < width - 1; x++) {
      const i = y * width + x;
      const gx =
        -gray[i - width - 1] - 2 * gray[i - 1] - gray[i + width - 1] +
        gray[i - width + 1] + 2 * gray[i + 1] + gray[i + width + 1];
      out[i] = Math.abs(gx);
    }
  }
  return out;
}

/** Otsu 自适应阈值二值化，返回 Uint8Array（1=前景）。 */
export function binarize(gray, width, height, invert = false) {
  const hist = new Array(256).fill(0);
  for (let i = 0; i < gray.length; i++) hist[Math.min(255, gray[i] | 0)]++;
  const total = gray.length;
  let sum = 0;
  for (let t = 0; t < 256; t++) sum += t * hist[t];
  let sumB = 0, wB = 0, best = 0, threshold = 127;
  for (let t = 0; t < 256; t++) {
    wB += hist[t];
    if (wB === 0) continue;
    const wF = total - wB;
    if (wF === 0) break;
    sumB += t * hist[t];
    const mB = sumB / wB, mF = (sum - sumB) / wF;
    const between = wB * wF * (mB - mF) * (mB - mF);
    if (between > best) { best = between; threshold = t; }
  }
  const out = new Uint8Array(width * height);
  for (let i = 0; i < gray.length; i++) {
    const fg = gray[i] > threshold;
    out[i] = invert ? (fg ? 0 : 1) : (fg ? 1 : 0);
  }
  return { bits: out, threshold };
}
