/**
 * 滑块缺口定位：纯函数，输入背景图（含缺口），输出缺口左缘 x 坐标与置信度。
 * 算法：水平梯度 -> 列向边缘能量 -> 搜索"左缘+右缘"峰值对（间距符合缺口宽度），
 * 以峰值对相对背景能量的对比度作为置信度。噪点/渐变/伪缺口下保持稳健。
 */
import { toGray, gradX } from './image.js';

export const SLIDER_DEFAULTS = {
  minGapWidth: 30,
  maxGapWidth: 70,
  minX: 40,            // 缺口不会出现在最左端（滑块起始区）
  confidenceThreshold: 0.35,
};

export function locateGap(img, options = {}) {
  const opts = { ...SLIDER_DEFAULTS, ...options };
  const { width, height } = img;
  const gray = toGray(img);
  const gx = gradX(gray, width, height);

  // 列向边缘能量（去掉上下边缘 10% 以避开边框干扰）
  const y0 = Math.floor(height * 0.1), y1 = Math.ceil(height * 0.9);
  const energy = new Float64Array(width);
  for (let x = 1; x < width - 1; x++) {
    let s = 0;
    for (let y = y0; y < y1; y++) s += gx[y * width + x];
    energy[x] = s / (y1 - y0);
  }
  // 轻微平滑抑制噪点尖峰
  const sm = new Float64Array(width);
  for (let x = 1; x < width - 1; x++) sm[x] = (energy[x - 1] + 2 * energy[x] + energy[x + 1]) / 4;

  let mean = 0;
  for (let x = 1; x < width - 1; x++) mean += sm[x];
  mean /= width - 2;
  if (mean <= 0) return { action: 'skip', reason: 'no-edges', confidence: 0 };

  // 候选边缘列：能量显著高于均值
  const isPeak = new Uint8Array(width);
  for (let x = 2; x < width - 2; x++) {
    if (sm[x] > mean * 2.2 && sm[x] >= sm[x - 1] && sm[x] >= sm[x + 1]) isPeak[x] = 1;
  }

  // 搜索峰值对 (left, right)，间距在缺口宽度范围内，取联合得分最高者
  let best = null;
  for (let l = opts.minX; l < width - opts.minGapWidth; l++) {
    if (!isPeak[l]) continue;
    for (let w = opts.minGapWidth; w <= opts.maxGapWidth; w++) {
      const r = l + w;
      if (r >= width - 1) break;
      if (!isPeak[r]) continue;
      const pairScore = sm[l] + sm[r];
      if (!best || pairScore > best.pairScore) best = { x: l, gapWidth: w, pairScore };
    }
  }
  if (!best) return { action: 'skip', reason: 'no-gap-pair', confidence: 0 };

  // 置信度：峰值对能量相对背景均值的超出比例，归一化到 [0,1]
  const confidence = Math.max(0, Math.min(1, (best.pairScore / 2 - mean * 2.2) / (mean * 4)));
  if (confidence < opts.confidenceThreshold) {
    return { action: 'skip', reason: 'low-confidence', confidence, x: best.x };
  }
  return { action: 'solve', x: best.x, gapWidth: best.gapWidth, confidence };
}
EOF
