{"cmd": "cat > /Users/gbr/Downloads/coding-agent-eval/task3-captcha/A/core/trajectory.js <<'EOF'
/**
 * 拟人拖动轨迹生成：纯函数。
 * 统计特征：总时长随距离增长（类 Fitts）、速度先升后降（bell 曲线）、
 * 中途随机抖动、末端过冲 + 回拉修正、随机微停顿。
 */

function mulberry32(seed) {
  let a = seed >>> 0;
  return function () {
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/**
 * @param {number} distance 目标水平距离（px）
 * @param {object} opts { seed, steps }
 * @returns {{points: Array<{x,y,t}>, duration: number, overshoot: number}}
 */
export function generateTrajectory(distance, opts = {}) {
  const rand = mulberry32(opts.seed ?? (Math.random() * 2 ** 31));
  const steps = opts.steps ?? Math.max(24, Math.round(distance / 4));
  // 时长：类 Fitts 定律 + 随机扰动
  const duration = Math.round(380 + 520 * Math.log2(1 + distance / 60) + rand() * 260);
  // 过冲：超出目标 2~8px，随后回拉
  const overshoot = 2 + rand() * 6;
  const overshootAt = 0.82 + rand() * 0.08; // 过冲峰值出现的时间比例

  const points = [];
  let jitterY = 0;
  // 随机 1~2 个微停顿时刻
  const pauses = [];
  const nPauses = 1 + Math.floor(rand() * 2);
  for (let i = 0; i < nPauses; i++) pauses.push(0.25 + rand() * 0.5);

  for (let i = 0; i <= steps; i++) {
    let p = i / steps; // 0..1
    // 主运动：两段式 ease —— 先加速冲到过冲点，再缓慢回拉到目标
    let x;
    if (p <= overshootAt) {
      const q = p / overshootAt;
      const eased = 1 - Math.pow(1 - q, 3); // easeOutCubic：快启动缓接近
      x = (distance + overshoot) * eased;
    } else {
      const q = (p - overshootAt) / (1 - overshootAt);
      const eased = q * q * (3 - 2 * q); // smoothstep 回拉
      x = distance + overshoot * (1 - eased);
    }
    // 中途抖动（不作用于首尾，保证起止精确）
    let jx = 0;
    if (i > 0 && i < steps) {
      jx = (rand() - 0.5) * 1.6;
      jitterY = jitterY * 0.6 + (rand() - 0.5) * 2.2;
    }
    let t = (p * duration);
    for (const pause of pauses) {
      if (Math.abs(p - pause) < 0.02) t += 30 + rand() * 60; // 微停顿
    }
    points.push({
      x: Math.round((i === steps ? distance : x + jx) * 100) / 100,
      y: Math.round((i === 0 || i === steps ? 0 : jitterY) * 100) / 100,
      t: Math.round(t),
    });
  }
  return { points, duration, overshoot };
}

/** 轨迹统计特征（供测试断言与扩展自检）。 */
export function trajectoryStats(traj) {
  const pts = traj.points;
  const n = pts.length;
  const speeds = [];
  for (let i = 1; i < n; i++) {
    const dt = Math.max(1e-6, pts[i].t - pts[i - 1].t);
    speeds.push(Math.abs(pts[i].x - pts[i - 1].x) / dt);
  }
  const maxSpeed = Math.max(...speeds);
  const maxSpeedIdx = speeds.indexOf(maxSpeed);
  const endX = pts[n - 1].x;
  const peakX = Math.max(...pts.map(p => p.x));
  const yJitter = Math.max(...pts.map(p => Math.abs(p.y)));
  return {
    duration: pts[n - 1].t - pts[0].t,
    steps: n,
    endX,
    peakX,
    hasOvershoot: peakX > endX + 0.5,
    startSpeed: speeds[0],
    endSpeed: speeds[n - 2],
    maxSpeed,
    maxSpeedAt: maxSpeedIdx / (n - 1), // 归一化时刻，bell 曲线应在中段
    yJitter,
  };
}
EOF
