    for (let x = x0; x <= x1; x++) for (let y = 0; y < height; y++) {
      if (bits[y * width + x]) { if (y < y0) y0 = y; if (y > y1) y1 = y; }
    }
    return { x0, x1, y0, y1 };
  });
}

export function recognizeChars(img, options = {}) {
  const opts = { ...CHAR_DEFAULTS, ...options };
