    const best = scores[0], second = scores[1];
    // 置信度：最优与次优的距离间隔，相对 35 个像素归一化
    const conf = Math.max(0, (second.dist - best.dist) / 35);
    chars.push({ ch: best.ch, confidence: conf, distance: best.dist });
    if (conf < minConf) minConf = conf;
  }
  const text = chars.map(c => c.ch).join('');
  if (minConf < opts.confidenceThreshold) {
    return { action: 'skip', reason: 'low-confidence', confidence: minConf, text, chars };
  }
  return { action: 'solve', text, confidence: minConf, chars };
}
