import { test } from 'node:test';
import assert from 'node:assert/strict';
import { locateGap } from '../core/index.js';
import { loadManifest, loadRaw } from './helpers.js';

const ERROR_TOLERANCE_PX = 3;
const MIN_SUCCESS_RATE = 0.95;

test('缺口定位：误差 ≤ 3px 且成功率 ≥ 95%（噪点/渐变/伪缺口干扰下）', () => {
  const man = loadManifest();
  let solved = 0;
  const failures = [];
  for (const entry of man.slider) {
    const r = locateGap(loadRaw('slider', entry));
    if (r.action === 'solve' && Math.abs(r.x - entry.gapX) <= ERROR_TOLERANCE_PX) {
      solved++;
    } else {
      failures.push({ file: entry.file, expected: entry.gapX, got: r.x, action: r.action });
    }
  }
