(async () => {
  const core = await import(chrome.runtime.getURL('core/index.js'));

  function setStatus(widget, text, ok) {
    let el = widget.querySelector('[data-role="status"]');
    if (!el) {
      el = document.createElement('div');
      el.dataset.role = 'status';
      widget.appendChild(el);
    }
    el.textContent = `[extension] ${text}`;
    el.style.color = ok === undefined ? '#666' : ok ? '#0a0' : '#c00';
  }

  function canvasImage(canvas) {
