/** 演示页：在页面内合成验证码（与 fixtures/generate.py 同思路），不加载任何远程资源。 */
import { FONT } from '../core/font.js';

const CHARSET = Object.keys(FONT).filter(c => c !== '1' && c !== 'I');
const rand = (a, b) => a + Math.random() * (b - a);
const randInt = (a, b) => Math.floor(rand(a, b + 1));

/* ---------- 滑块 ---------- */
const sliderCanvas = document.getElementById('slider-canvas');
const handle = document.querySelector('[data-role="handle"]');
const sliderWidget = document.getElementById('slider-widget');
let gapX = 0, gapW = 0, handleX = 0, dragging = false, dragOrigin = 0, dragStartX = 0;

function drawSlider() {
  const ctx = sliderCanvas.getContext('2d');
  const W = sliderCanvas.width, H = sliderCanvas.height;
  const g = ctx.createLinearGradient(0, 0, W, H);
  g.addColorStop(0, `rgb(${randInt(60,160)},${randInt(60,160)},${randInt(80,180)})`);
  g.addColorStop(1, `rgb(${randInt(120,230)},${randInt(120,230)},${randInt(120,230)})`);
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, W, H);
  for (let i = 0; i < 6; i++) { // 纹理
    ctx.strokeStyle = `rgba(${randInt(0,255)},${randInt(0,255)},${randInt(0,255)},0.6)`;
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.arc(rand(0, W), rand(0, H), rand(8, 30), 0, Math.PI * 2);
    ctx.stroke();
  }
  gapW = randInt(34, 52);
  gapX = randInt(120, W - gapW - 10);
  const gapY = randInt(20, H - 70);
  // 伪缺口
  const fx = randInt(10, 90);
  ctx.fillStyle = 'rgba(40,40,50,0.35)';
  ctx.fillRect(fx, randInt(10, 90), gapW, 40);
  // 真缺口
  ctx.fillStyle = 'rgb(45,45,55)';
  ctx.fillRect(gapX, gapY, gapW, 42);
  ctx.strokeStyle = 'rgb(30,30,30)';
  ctx.lineWidth = 2;
  ctx.strokeRect(gapX, gapY, gapW, 42);
  for (let i = 0; i < 3000; i++) { // 噪点
    const v = randInt(0, 255);
    ctx.fillStyle = `rgba(${v},${v},${v},0.35)`;
    ctx.fillRect(rand(0, W), rand(0, H), 1, 1);
  }
  handleX = 0;
  handle.dataset.x = '0';
  handle.style.left = '0px';
  verdict(sliderWidget, '', null);
  delete sliderWidget.dataset.solved;
}

function verdict(widget, text, ok) {
  const el = widget.querySelector('[data-role="verdict"]');
  el.textContent = text;
  el.style.color = ok ? '#0a0' : '#c00';
}

handle.addEventListener('mousedown', e => {
  dragging = true;
  dragOrigin = e.clientX;
  dragStartX = handleX;
  e.preventDefault();
});
document.addEventListener('mousemove', e => {
  if (!dragging) return;
  handleX = Math.max(0, Math.min(260, dragStartX + e.clientX - dragOrigin));
  handle.dataset.x = String(handleX);
  handle.style.left = handleX + 'px';
});
document.addEventListener('mouseup', () => {
  if (!dragging) return;
  dragging = false;
  if (Math.abs(handleX - gapX) <= 4) {
    verdict(sliderWidget, '✔ 通过', true);
  } else {
    verdict(sliderWidget, `✘ 未对齐（差 ${Math.abs(handleX - gapX)}px），已复位`, false);
    handleX = 0;
    handle.dataset.x = '0';
    handle.style.left = '0px';
  }
});

/* ---------- 字符 ---------- */
const charsCanvas = document.getElementById('chars-canvas');
const charsInput = document.getElementById('chars-input');
const charsWidget = document.getElementById('chars-widget');
let charsAnswer = '';

function drawChars() {
  const ctx = charsCanvas.getContext('2d');
  const W = charsCanvas.width, H = charsCanvas.height;
  ctx.fillStyle = 'rgb(245,245,240)';
  ctx.fillRect(0, 0, W, H);
  const n = 4;
  const scale = 5;
  charsAnswer = '';
  for (let i = 0; i < n; i++) {
    const ch = CHARSET[randInt(0, CHARSET.length - 1)];
    charsAnswer += ch;
    const ox = 14 + i * 50 + randInt(-2, 2);
    const oy = 10 + randInt(-3, 3);
    const shade = randInt(0, 90);
    ctx.fillStyle = `rgb(${shade},${shade},${shade + randInt(0, 30)})`;
    FONT[ch].forEach((row, gy) => {
      for (let gx = 0; gx < 5; gx++) {
        if (row[gx] === '1') ctx.fillRect(ox + gx * scale, oy + gy * scale, scale, scale);
      }
    });
  }
  for (let i = 0; i < 3; i++) { // 干扰线
    ctx.strokeStyle = `rgba(${randInt(120,200)},${randInt(120,200)},${randInt(120,200)},0.8)`;
    ctx.beginPath();
    ctx.moveTo(rand(0, W), rand(0, H));
    ctx.lineTo(rand(0, W), rand(0, H));
    ctx.stroke();
  }
  for (let i = 0; i < 250; i++) {
    const v = randInt(0, 255);
    ctx.fillStyle = `rgb(${v},${v},${v})`;
    ctx.fillRect(rand(0, W), rand(0, H), 1, 1);
  }
  charsInput.value = '';
  verdict(charsWidget, '', null);
  delete charsWidget.dataset.solved;
}

charsWidget.querySelector('[data-role="verify"]').addEventListener('click', () => {
  const ok = charsInput.value.trim().toUpperCase() === charsAnswer;
  verdict(charsWidget, ok ? '✔ 通过' : '✘ 错误', ok);
});

document.getElementById('regen').addEventListener('click', () => { drawSlider(); drawChars(); });
drawSlider();
drawChars();
